// Offline cache for Exercise Timer. NOT a timer: it only serves files.
// The BUILD/ASSETS block is generated by `node tools/build-assets.mjs`; a new
// BUILD makes this file differ, which is how browsers notice an update.
// A new version installs in the background and waits; it only takes over when
// the app asks (at an idle moment), so cached files from two versions never mix.

// BEGIN GENERATED
const BUILD = '8f541a9c8e9e';
const ASSETS = ["./","./IOS_Install_Instructions.txt","./help.html","./icons/apple-touch-icon.png","./icons/icon-192.png","./icons/icon-512.png","./icons/maskable-512.png","./index.html","./js/app.js","./js/engine.js","./js/sound.js","./js/store.js","./js/transfer.js","./manifest.webmanifest","./styles.css"];
// END GENERATED

const PREFIX = 'exercise-timer-';
const CACHE = `${PREFIX}${BUILD}`;
const key = (u) => new URL(u, self.registration.scope).href;

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    // all-or-nothing: a missing file fails the install, so "ready" is never claimed early
    await Promise.all(ASSETS.map(async (u) => {
      const res = await fetch(new Request(key(u), { cache: 'reload' }));
      if (!res.ok) throw new Error(`could not cache ${u}`);
      await cache.put(key(u), res);
    }));
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const name of await caches.keys()) if (name.startsWith(PREFIX) && name !== CACHE) await caches.delete(name);
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin || !url.href.startsWith(self.registration.scope)) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const hit = await cache.match(req, { ignoreSearch: true });
    if (hit) return hit;
    try { return await fetch(req); } catch (err) {
      if (req.mode === 'navigate') {
        const home = await cache.match(key('./'));
        if (home) return home;
      }
      throw err;
    }
  })());
});

self.addEventListener('message', (event) => {
  const msg = event.data || {};
  if (msg.type === 'SKIP_WAITING') self.skipWaiting();
  if (msg.type === 'STATUS' && event.ports[0]) {
    event.waitUntil((async () => {
      const cache = await caches.open(CACHE);
      let ready = true;
      for (const u of ASSETS) if (!(await cache.match(key(u)))) ready = false;
      event.ports[0].postMessage({ ready, build: BUILD, count: ASSETS.length });
    })());
  }
});
